create or replace function public.list_customers(p_q text default null, p_limit int default 200) returns jsonb language plpgsql stable security definer set search_path = public as $$ declare v_store uuid := public.current_store_id(); v_lim int := greatest(1, least(coalesce(p_limit, 200), 500)); v_q text := nullif(btrim(coalesce(p_q, '')), ''); v_rows jsonb; v_point int; begin perform public.assert_manager(); if v_store is null then raise exception 'no_store' using errcode = 'P0001'; end if; v_point := greatest(public.store_setting_int(v_store, 'rewards_point_value_cents', 1), 0); select coalesce(jsonb_agg(row_to_json(x)::jsonb order by x.last_visit desc nulls last, x.created_at desc), '[]'::jsonb) into v_rows from ( select c.id, c.phone, c.name, c.email, c.marketing_opt_in, (c.unsubscribed_at is not null) as unsubscribed, c.first_purchase_discount_used, c.signup_code, c.created_at, public.customer_points_balance_internal(v_store, c.id) as points, public.customer_points_balance_internal(v_store, c.id) * v_point as credit_cents, coalesce((select sum(s.price_cents)::bigint from public.ticket_extras te join public.sales s on s.ticket_id = te.ticket_id and s.store_id = v_store where te.customer_id = c.id and te.store_id = v_store and s.voided_at is null and s.channel in ('floor', 'website')), 0) as spend_cents, (select max(s.sold_at) from public.ticket_extras te join public.sales s on s.ticket_id = te.ticket_id and s.store_id = v_store where te.customer_id = c.id and te.store_id = v_store and s.voided_at is null and s.channel in ('floor', 'website')) as last_visit from public.customers c where c.store_id = v_store and (v_q is null or (regexp_replace(v_q, '\D', '', 'g') <> '' and c.phone like '%' || regexp_replace(v_q, '\D', '', 'g') || '%') or c.name ilike '%' || v_q || '%' or c.email ilike '%' || v_q || '%') order by last_visit desc nulls last, c.created_at desc limit v_lim) x; return v_rows; end; $$;
create or replace function public.adjust_customer_points(p_customer_id uuid, p_delta int, p_note text default null) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_store uuid := public.current_store_id(); r public.customers; v_bal int; v_next int; begin perform public.assert_manager(); if v_store is null then raise exception 'no_store' using errcode = 'P0001'; end if; if p_delta is null or p_delta = 0 then raise exception 'delta_required' using errcode = '22023'; end if; select * into r from public.customers where id = p_customer_id and store_id = v_store; if not found then raise exception 'customer_not_found' using errcode = 'P0001'; end if; v_bal := public.customer_points_balance_internal(v_store, r.id); v_next := v_bal + p_delta; if v_next < 0 then raise exception 'insufficient_points' using errcode = 'P0001'; end if; insert into public.customer_points_ledger (store_id, customer_id, delta, balance_after, reason, actor_id) values (v_store, r.id, p_delta, v_next, 'adjust', auth.uid()); return public.customer_card(v_store, r) || jsonb_build_object('note', nullif(btrim(coalesce(p_note, '')), '')); end; $$;;
